package com.portfolio.fraud.repository; import com.portfolio.fraud.entity.Account; import java.util.*; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; public interface AccountRepository extends JpaRepository<Account,Long>{@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from Account a where a.id=:id") Optional<Account> findByIdForUpdate(Long id); List<Account> findByUserId(Long userId);}
